## ECS

### `src/ecs/Entity.js`

```javascript
let nextId = 1;

export class Entity {
    constructor() {
        this.id = nextId++;
        this.components = new Map();
        this.active = true;
    }

    add(component) {
        this.components.set(component.constructor, component);
        return this;
    }

    get(type) {
        return this.components.get(type);
    }

    has(type) {
        return this.components.has(type);
    }
}
```

### `src/ecs/World.js`

```javascript
import { Entity } from "./Entity.js";

export class World {
    constructor() {
        this.entities = new Map();
        this.systems = [];
    }

    createEntity() {
        const e = new Entity();
        this.entities.set(e.id, e);
        return e;
    }

    addSystem(system) {
        system.world = this;
        this.systems.push(system);
    }

    query(...types) {
        return [...this.entities.values()]
            .filter(e => types.every(t => e.has(t)));
    }

    update(dt) {
        for (const system of this.systems)
            system.update?.(dt);
    }
}
```

