### `src/components/Animation.js`

```javascript
export class Animation {
    constructor(frameWidth, frameHeight, count, speed = 0.1) {
        this.frameWidth = frameWidth;
        this.frameHeight = frameHeight;
        this.count = count;
        this.speed = speed;
        this.frame = 0;
        this.elapsed = 0;
    }

    update(dt) {
        this.elapsed += dt;

        if (this.elapsed >= this.speed) {
            this.elapsed = 0;
            this.frame = (this.frame + 1) % this.count;
        }
    }
}
