## Input

### `src/core/Input.js`

```javascript
export class Input {
    constructor() {
        this.keys = new Set();
        this.previous = new Set();

        addEventListener("keydown", e => this.keys.add(e.code));
        addEventListener("keyup", e => this.keys.delete(e.code));
    }

    update() {
        this.previous = new Set(this.keys);
    }

    down(key) {
        return this.keys.has(key);
    }

    pressed(key) {
        return this.keys.has(key) && !this.previous.has(key);
    }
}
```

## Physics

### `src/physics/PhysicsSystem.js`

```javascript
import { Transform } from "../components/Transform.js";
import { Velocity } from "../components/Velocity.js";
import { Collider } from "../components/Collider.js";

export class PhysicsSystem {
    constructor(gravity = 1200) {
        this.gravity = gravity;
    }

    update(dt) {
        for (const e of this.world.query(
            Transform, Velocity, Collider
        )) {
            const t = e.get(Transform);
            const v = e.get(Velocity);
            const c = e.get(Collider);

            if (c.isStatic) continue;

            v.y += this.gravity * dt;
            t.x += v.x * dt;
            t.y += v.y * dt;
        }
    }
}
```

### `src/physics/CollisionSystem.js`

```javascript
import { Transform } from "../components/Transform.js";
import { Velocity } from "../components/Velocity.js";
import { Collider } from "../components/Collider.js";

function hit(a, b) {
    return (
        a.x < b.x + b.width &&
        a.x + a.width > b.x &&
        a.y < b.y + b.height &&
        a.y + a.height > b.y
    );
}

export class CollisionSystem {
    update() {
        const all = this.world.query(Transform, Collider);
        const statics = all.filter(e => e.get(Collider).isStatic);

        for (const e of all) {
            const c = e.get(Collider);
            if (c.isStatic) continue;

            const t = e.get(Transform);
            const v = e.get(Velocity);

            c.onGround = false;

            for (const wall of statics) {
                const wt = wall.get(Transform);
                const wc = wall.get(Collider);

                if (!hit(
                    { x: t.x, y: t.y, width: c.width, height: c.height },
                    { x: wt.x, y: wt.y, width: wc.width, height: wc.height }
                )) continue;

                if (v.y > 0) {
                    t.y = wt.y - c.height;
                    c.onGround = true;
                } else if (v.y < 0) {
                    t.y = wt.y + wc.height;
                }

                v.y = 0;
            }
        }
    }
}
```

## Player system

### `src/systems/PlayerSystem.js`

```javascript
import { Velocity } from "../components/Velocity.js";
import { Collider } from "../components/Collider.js";
import { Sprite } from "../components/Sprite.js";

export class PlayerSystem {
    constructor(input) {
        this.input = input;
        this.speed = 250;
        this.jump = 500;
    }

    update() {
        for (const e of this.world.query(
            Velocity, Collider, Sprite
        )) {
            if (!e.player) continue;

            const v = e.get(Velocity);
            const c = e.get(Collider);
            const s = e.get(Sprite);

            v.x = 0;

            if (this.input.down("ArrowLeft")) {
                v.x = -this.speed;
                s.flipX = true;
            }

            if (this.input.down("ArrowRight")) {
                v.x = this.speed;
                s.flipX = false;
            }

            if (this.input.pressed("Space") && c.onGround)
                v.y = -this.jump;
        }
    }
}
```

