## Camera

### `src/rendering/Camera.js`

```javascript
import { Transform } from "../components/Transform.js";

export class Camera {
    constructor() {
        this.x = 0;
        this.y = 0;
        this.target = null;
    }

    follow(entity) {
        this.target = entity;
    }

    update(dt) {
        if (!this.target) return;

        const t = this.target.get(Transform);

        const tx = t.x - innerWidth / 2;
        const ty = t.y - innerHeight / 2;

        this.x += (tx - this.x) * Math.min(1, 8 * dt);
        this.y += (ty - this.y) * Math.min(1, 8 * dt);
    }
}
```

## Renderer

### `src/rendering/Renderer.js`

```javascript
import { Transform } from "../components/Transform.js";
import { Sprite } from "../components/Sprite.js";
import { Animation } from "../components/Animation.js";

export class Renderer {
    constructor(canvas, camera) {
        this.ctx = canvas.getContext("2d");
        this.canvas = canvas;
        this.camera = camera;
    }

    resize() {
        this.canvas.width = innerWidth;
        this.canvas.height = innerHeight;
    }

    render(world) {
        const ctx = this.ctx;

        ctx.fillStyle = "#202030";
        ctx.fillRect(0, 0, innerWidth, innerHeight);

        for (const e of world.query(Transform)) {
            const t = e.get(Transform);
            const s = e.get(Sprite);

            const x = t.x - this.camera.x;
            const y = t.y - this.camera.y;

            if (!s) {
                ctx.fillStyle = "#55aaff";
                ctx.fillRect(x, y, t.width, t.height);
                continue;
            }

            const a = e.get(Animation);
            const frame = a?.frame ?? 0;
            const fw = a?.frameWidth ?? s.width;
            const fh = a?.frameHeight ?? s.height;

            ctx.save();

            if (s.flipX) {
                ctx.translate(x + t.width, y);
                ctx.scale(-1, 1);
                ctx.drawImage(
                    s.image,
                    frame * fw, 0, fw, fh,
                    0, 0, t.width, t.height
                );
            } else {
                ctx.drawImage(
                    s.image,
                    frame * fw, 0, fw, fh,
                    x, y, t.width, t.height
                );
            }

            ctx.restore();
        }
    }
}
```

## Save/load

### `src/save/SaveManager.js`

```javascript
import { Transform } from "../components/Transform.js";

export class SaveManager {
    constructor(key = "game-save") {
        this.key = key;
    }

    save(player) {
        const t = player.get(Transform);

        localStorage.setItem(this.key, JSON.stringify({
            version: 1,
            player: { x: t.x, y: t.y }
        }));
    }

    load(player) {
        const raw = localStorage.getItem(this.key);
        if (!raw) return false;

        const data = JSON.parse(raw);
        const t = player.get(Transform);

        t.x = data.player.x;
        t.y = data.player.y;

        return true;
    }
}
```

## Game loop

### `src/core/Game.js`

```javascript
export class Game {
    constructor(world, renderer, camera, input) {
        this.world = world;
        this.renderer = renderer;
        this.camera = camera;
        this.input = input;
        this.last = performance.now();
    }

    start() {
        this.renderer.resize();

        addEventListener(
            "resize",
            () => this.renderer.resize()
        );

        requestAnimationFrame(this.loop.bind(this));
    }

    loop(now) {
        const dt = Math.min(
            (now - this.last) / 1000,
            0.1
        );

        this.last = now;

        this.input.update();
        this.world.update(dt);
        this.camera.update(dt);
        this.renderer.render(this.world);

        requestAnimationFrame(this.loop.bind(this));
    }
}
```

