package kvdb

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"os"
	"sort"
)

var (
	walMagic  = [8]byte{'K', 'V', 'W', 'A', 'L', '0', '0', '1'}
	snapMagic = [8]byte{'K', 'V', 'S', 'N', 'A', 'P', '0', '1'}
)

const (
	opPut    = byte(1)
	opDelete = byte(2)

	maxFrameSize = 1 << 30 // 1 GiB sanity limit
)

var ErrCorrupt = errors.New("kvdb: corrupt database")

type operation struct {
	kind  byte
	key   string
	value []byte
}

func putU32(b *bytes.Buffer, v uint32) {
	var p [4]byte
	binary.BigEndian.PutUint32(p[:], v)
	b.Write(p[:])
}

func putU64(b *bytes.Buffer, v uint64) {
	var p [8]byte
	binary.BigEndian.PutUint64(p[:], v)
	b.Write(p[:])
}

func encodeTransaction(seq uint64, ops []operation) ([]byte, error) {
	var payload bytes.Buffer

	putU64(&payload, seq)
	if len(ops) > int(^uint32(0)) {
		return nil, errors.New("kvdb: too many operations")
	}
	putU32(&payload, uint32(len(ops)))

	for _, op := range ops {
		if uint64(len(op.key)) > uint64(^uint32(0)) ||
			uint64(len(op.value)) > uint64(^uint32(0)) {
			return nil, errors.New("kvdb: key or value too large")
		}

		payload.WriteByte(op.kind)
		putU32(&payload, uint32(len(op.key)))
		putU32(&payload, uint32(len(op.value)))
		payload.WriteString(op.key)

		if op.kind == opPut {
			payload.Write(op.value)
		} else if op.kind != opDelete {
			return nil, errors.New("kvdb: invalid operation")
		}
	}

	p := payload.Bytes()
	if len(p) > maxFrameSize {
		return nil, errors.New("kvdb: transaction too large")
	}

	var frame bytes.Buffer
	frame.Write(walMagic[:])
	putU32(&frame, uint32(len(p)))
	frame.Write(p)

	crc := crc32.ChecksumIEEE(p)
	putU32(&frame, crc)

	return frame.Bytes(), nil
}

func decodeTransaction(payload []byte) (uint64, []operation, error) {
	r := bytes.NewReader(payload)

	var seq uint64
	if err := binary.Read(r, binary.BigEndian, &seq); err != nil {
		return 0, nil, ErrCorrupt
	}

	var count uint32
	if err := binary.Read(r, binary.BigEndian, &count); err != nil {
		return 0, nil, ErrCorrupt
	}

	ops := make([]operation, 0, count)
	for i := uint32(0); i < count; i++ {
		kind, err := r.ReadByte()
		if err != nil {
			return 0, nil, ErrCorrupt
		}

		var kl, vl uint32
		if err := binary.Read(r, binary.BigEndian, &kl); err != nil {
			return 0, nil, ErrCorrupt
		}
		if err := binary.Read(r, binary.BigEndian, &vl); err != nil {
			return 0, nil, ErrCorrupt
		}

		if uint64(kl)+uint64(vl) > uint64(r.Len()) {
			return 0, nil, ErrCorrupt
		}

		k := make([]byte, kl)
		if _, err := io.ReadFull(r, k); err != nil {
			return 0, nil, ErrCorrupt
		}

		op := operation{kind: kind, key: string(k)}
		switch kind {
		case opPut:
			v := make([]byte, vl)
			if _, err := io.ReadFull(r, v); err != nil {
				return 0, nil, ErrCorrupt
			}
			op.value = v
		case opDelete:
			if vl != 0 {
				return 0, nil, ErrCorrupt
			}
		default:
			return 0, nil, ErrCorrupt
		}
		ops = append(ops, op)
	}

	if r.Len() != 0 {
		return 0, nil, ErrCorrupt
	}

	return seq, ops, nil
}

func encodeSnapshot(seq uint64, m map[string][]byte) ([]byte, error) {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var payload bytes.Buffer
	putU64(&payload, seq)

	if len(keys) > int(^uint32(0)) {
		return nil, errors.New("kvdb: too many keys")
	}
	putU32(&payload, uint32(len(keys)))

	for _, k := range keys {
		v := m[k]
		if uint64(len(k)) > uint64(^uint32(0)) ||
			uint64(len(v)) > uint64(^uint32(0)) {
			return nil, errors.New("kvdb: key or value too large")
		}

		putU32(&payload, uint32(len(k)))
		putU32(&payload, uint32(len(v)))
		payload.WriteString(k)
		payload.Write(v)
	}

	var out bytes.Buffer
	out.Write(snapMagic[:])
	putU64(&out, uint64(payload.Len()))
	out.Write(payload.Bytes())
	putU32(&out, crc32.ChecksumIEEE(payload.Bytes()))

	return out.Bytes(), nil
}

func decodeSnapshot(data []byte) (uint64, map[string][]byte, error) {
	if len(data) < 8+8+4 {
		return 0, nil, ErrCorrupt
	}
	if !bytes.Equal(data[:8], snapMagic[:]) {
		return 0, nil, ErrCorrupt
	}

	n := binary.BigEndian.Uint64(data[8:16])
	if n > uint64(len(data)-20) {
		return 0, nil, ErrCorrupt
	}
	if n != uint64(len(data)-20) {
		return 0, nil, ErrCorrupt
	}

	payload := data[16 : 16+n]
	want := binary.BigEndian.Uint32(data[16+n:])
	got := crc32.ChecksumIEEE(payload)
	if want != got {
		return 0, nil, fmt.Errorf("%w: snapshot checksum mismatch", ErrCorrupt)
	}

	r := bytes.NewReader(payload)

	var seq uint64
	if err := binary.Read(r, binary.BigEndian, &seq); err != nil {
		return 0, nil, ErrCorrupt
	}

	var count uint32
	if err := binary.Read(r, binary.BigEndian, &count); err != nil {
		return 0, nil, ErrCorrupt
	}

	m := make(map[string][]byte, count)
	for i := uint32(0); i < count; i++ {
		var kl, vl uint32
		if err := binary.Read(r, binary.BigEndian, &kl); err != nil {
			return 0, nil, ErrCorrupt
		}
		if err := binary.Read(r, binary.BigEndian, &vl); err != nil {
			return 0, nil, ErrCorrupt
		}

		if uint64(kl)+uint64(vl) > uint64(r.Len()) {
			return 0, nil, ErrCorrupt
		}

		k := make([]byte, kl)
		v := make([]byte, vl)
		if _, err := io.ReadFull(r, k); err != nil {
			return 0, nil, ErrCorrupt
		}
		if _, err := io.ReadFull(r, v); err != nil {
			return 0, nil, ErrCorrupt
		}

		if _, exists := m[string(k)]; exists {
			return 0, nil, ErrCorrupt
		}
		m[string(k)] = v
	}

	if r.Len() != 0 {
		return 0, nil, ErrCorrupt
	}

	return seq, m, nil
}

type recoveryResult struct {
	seq       uint64
	goodBytes int64
	tornTail  bool
}

func recoverWAL(f *os.File, m map[string][]byte, snapshotSeq uint64) (recoveryResult, error) {
	var result recoveryResult
	result.seq = snapshotSeq

	if _, err := f.Seek(0, io.SeekStart); err != nil {
		return result, err
	}

	var offset int64

	for {
		header := make([]byte, 12)
		n, err := io.ReadFull(f, header)

		if err == io.EOF && n == 0 {
			result.goodBytes = offset
			return result, nil
		}
		if err == io.ErrUnexpectedEOF || err == io.EOF {
			result.goodBytes = offset
			result.tornTail = true
			return result, nil
		}
		if err != nil {
			return result, err
		}

		if !bytes.Equal(header[:8], walMagic[:]) {
			return result, fmt.Errorf("%w: bad WAL magic at offset %d", ErrCorrupt, offset)
		}

		nPayload := binary.BigEndian.Uint32(header[8:])
		if nPayload > maxFrameSize {
			return result, fmt.Errorf("%w: invalid WAL frame length at offset %d", ErrCorrupt, offset)
		}

		body := make([]byte, int(nPayload)+4)
		n, err = io.ReadFull(f, body)
		if err == io.ErrUnexpectedEOF || err == io.EOF {
			result.goodBytes = offset
			result.tornTail = true
			return result, nil
		}
		if err != nil {
			return result, err
		}
		if n != len(body) {
			result.goodBytes = offset
			result.tornTail = true
			return result, nil
		}

		payload := body[:nPayload]
		want := binary.BigEndian.Uint32(body[nPayload:])
		got := crc32.ChecksumIEEE(payload)
		if want != got {
			// A checksum failure in the last physical frame is indistinguishable
			// from a torn sector/write. If more bytes follow, it is definite
			// corruption. If this is EOF, discard it as an uncommitted tail.
			pos, err := f.Seek(0, io.SeekCurrent)
			if err != nil {
				return result, err
			}
			st, err := f.Stat()
			if err != nil {
				return result, err
			}
			if pos != st.Size() {
				return result, fmt.Errorf("%w: WAL checksum mismatch at offset %d", ErrCorrupt, offset)
			}
			result.goodBytes = offset
			result.tornTail = true
			return result, nil
		}

		seq, ops, err := decodeTransaction(payload)
		if err != nil {
			return result, fmt.Errorf("%w: WAL transaction at offset %d", err, offset)
		}

		if seq > result.seq {
			if seq != result.seq+1 {
				return result, fmt.Errorf("%w: WAL sequence gap: have %d, got %d",
					ErrCorrupt, result.seq, seq)
			}
			applyOperations(m, ops)
			result.seq = seq
		}

		offset += int64(12 + len(body))
		result.goodBytes = offset
	}
}
