`db.go`
```go
package kvdb

import (
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sync"
)

const (
	walFileName      = "wal"
	snapshotFileName = "snapshot"
	tempFileName     = "snapshot.tmp"
)

type DB struct {
	mu     sync.RWMutex
	dir    string
	wal    *os.File
	data   map[string][]byte
	seq    uint64
	closed bool
}

func Open(dir string) (*DB, error) {
	if dir == "" {
		return nil, errors.New("kvdb: empty database directory")
	}

	if err := os.MkdirAll(dir, 0700); err != nil {
		return nil, err
	}

	db := &DB{
		dir:  dir,
		data: make(map[string][]byte),
	}

	snapPath := filepath.Join(dir, snapshotFileName)
	if b, err := os.ReadFile(snapPath); err == nil {
		seq, m, err := decodeSnapshot(b)
		if err != nil {
			return nil, err
		}
		db.seq = seq
		db.data = m
	} else if !os.IsNotExist(err) {
		return nil, err
	}

	walPath := filepath.Join(dir, walFileName)
	wal, err := os.OpenFile(walPath, os.O_RDWR|os.O_CREATE, 0600)
	if err != nil {
		return nil, err
	}
	db.wal = wal

	result, err := recoverWAL(wal, db.data, db.seq)
	if err != nil {
		wal.Close()
		return nil, err
	}
	db.seq = result.seq

	if result.tornTail {
		if err := wal.Truncate(result.goodBytes); err != nil {
			wal.Close()
			return nil, err
		}
		if err := wal.Sync(); err != nil {
			wal.Close()
			return nil, err
		}
	}

	if _, err := wal.Seek(0, io.SeekEnd); err != nil {
		wal.Close()
		return nil, err
	}

	// Persist creation of the WAL directory entry before returning Open.
	if err := syncDir(dir); err != nil {
		wal.Close()
		return nil, err
	}

	return db, nil
}

func (db *DB) Get(key string) ([]byte, bool, error) {
	db.mu.RLock()
	defer db.mu.RUnlock()

	if db.closed {
		return nil, false, errors.New("kvdb: closed")
	}

	v, ok := db.data[key]
	if !ok {
		return nil, false, nil
	}
	out := append([]byte(nil), v...)
	return out, true, nil
}

func (db *DB) Put(key string, value []byte) error {
	tx, err := db.Begin(true)
	if err != nil {
		return err
	}
	if err := tx.Put(key, value); err != nil {
		tx.Rollback()
		return err
	}
	return tx.Commit()
}

func (db *DB) Delete(key string) error {
	tx, err := db.Begin(true)
	if err != nil {
		return err
	}
	if err := tx.Delete(key); err != nil {
		tx.Rollback()
		return err
	}
	return tx.Commit()
}

func (db *DB) Close() error {
	db.mu.Lock()
	defer db.mu.Unlock()

	if db.closed {
		return nil
	}
	db.closed = true

	if db.wal != nil {
		return db.wal.Close()
	}
	return nil
}

func (db *DB) Compact() error {
	db.mu.Lock()
	defer db.mu.Unlock()

	if db.closed {
		return errors.New("kvdb: closed")
	}

	image, err := encodeSnapshot(db.seq, db.data)
	if err != nil {
		return err
	}

	tmp := filepath.Join(db.dir, tempFileName)
	snap := filepath.Join(db.dir, snapshotFileName)

	_ = os.Remove(tmp)

	f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		return err
	}

	ok := false
	defer func() {
		f.Close()
		if !ok {
			os.Remove(tmp)
		}
	}()

	if err := writeFull(f, image); err != nil {
		return err
	}
	if err := f.Sync(); err != nil {
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}

	if err := os.Rename(tmp, snap); err != nil {
		return err
	}

	// Makes the snapshot rename durable before removing WAL history.
	if err := syncDir(db.dir); err != nil {
		return err
	}

	if err := db.wal.Truncate(0); err != nil {
		return err
	}
	if _, err := db.wal.Seek(0, io.SeekStart); err != nil {
		return err
	}
	if err := db.wal.Sync(); err != nil {
		return err
	}

	// File size is metadata. Syncing the file above is the primary guarantee;
	// sync the directory as an additional metadata barrier.
	if err := syncDir(db.dir); err != nil {
		return err
	}

	ok = true
	return nil
}

func (db *DB) Inspect() (Info, error) {
	db.mu.RLock()
	defer db.mu.RUnlock()

	if db.closed {
		return Info{}, errors.New("kvdb: closed")
	}

	st, err := db.wal.Stat()
	if err != nil {
		return Info{}, err
	}

	_, snapErr := os.Stat(filepath.Join(db.dir, snapshotFileName))
	hasSnapshot := snapErr == nil
	if snapErr != nil && !os.IsNotExist(snapErr) {
		return Info{}, snapErr
	}

	return Info{
		Directory:   db.dir,
		Sequence:    db.seq,
		Keys:        len(db.data),
		WALBytes:    st.Size(),
		HasSnapshot: hasSnapshot,
	}, nil
}

type Info struct {
	Directory   string
	Sequence    uint64
	Keys        int
	WALBytes    int64
	HasSnapshot bool
}

func applyOperations(m map[string][]byte, ops []operation) {
	for _, op := range ops {
		switch op.kind {
		case opPut:
			m[op.key] = append([]byte(nil), op.value...)
		case opDelete:
			delete(m, op.key)
		}
	}
}

func writeFull(w io.Writer, p []byte) error {
	for len(p) != 0 {
		n, err := w.Write(p)
		if err != nil {
			return err
		}
		if n == 0 {
			return io.ErrShortWrite
		}
		p = p[n:]
	}
	return nil
}

func syncDir(path string) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()

	if err := f.Sync(); err != nil {
		return fmt.Errorf("kvdb: sync directory: %w", err)
	}
	return nil
}
