`tx.go`
```go
package kvdb

import (
	"errors"
)

type Tx struct {
	db       *DB
	writable bool
	done     bool
	ops      []operation
	view     map[string][]byte
}

func (db *DB) Begin(writable bool) (*Tx, error) {
	if writable {
		db.mu.Lock()
	} else {
		db.mu.RLock()
	}

	if db.closed {
		if writable {
			db.mu.Unlock()
		} else {
			db.mu.RUnlock()
		}
		return nil, errors.New("kvdb: closed")
	}

	tx := &Tx{
		db:       db,
		writable: writable,
	}

	if writable {
		// A private transaction view provides read-your-writes without
		// exposing uncommitted state through db.data.
		tx.view = cloneMap(db.data)
	}

	return tx, nil
}

func (tx *Tx) Get(key string) ([]byte, bool, error) {
	if tx.done {
		return nil, false, errors.New("kvdb: transaction closed")
	}

	var m map[string][]byte
	if tx.writable {
		m = tx.view
	} else {
		m = tx.db.data
	}

	v, ok := m[key]
	if !ok {
		return nil, false, nil
	}
	return append([]byte(nil), v...), true, nil
}

func (tx *Tx) Put(key string, value []byte) error {
	if tx.done {
		return errors.New("kvdb: transaction closed")
	}
	if !tx.writable {
		return errors.New("kvdb: read-only transaction")
	}
	if uint64(len(key)) > uint64(^uint32(0)) ||
		uint64(len(value)) > uint64(^uint32(0)) {
		return errors.New("kvdb: key or value too large")
	}

	v := append([]byte(nil), value...)
	tx.ops = append(tx.ops, operation{
		kind:  opPut,
		key:   key,
		value: v,
	})
	tx.view[key] = append([]byte(nil), v...)
	return nil
}

func (tx *Tx) Delete(key string) error {
	if tx.done {
		return errors.New("kvdb: transaction closed")
	}
	if !tx.writable {
		return errors.New("kvdb: read-only transaction")
	}
	if uint64(len(key)) > uint64(^uint32(0)) {
		return errors.New("kvdb: key too large")
	}

	tx.ops = append(tx.ops, operation{
		kind: opDelete,
		key:  key,
	})
	delete(tx.view, key)
	return nil
}

func (tx *Tx) Commit() error {
	if tx.done {
		return errors.New("kvdb: transaction closed")
	}

	tx.done = true

	if !tx.writable {
		tx.db.mu.RUnlock()
		return nil
	}
	defer tx.db.mu.Unlock()

	if len(tx.ops) == 0 {
		return nil
	}

	seq := tx.db.seq + 1
	frame, err := encodeTransaction(seq, tx.ops)
	if err != nil {
		return err
	}

	if _, err := tx.db.wal.Seek(0, 2); err != nil {
		return err
	}

	if err := writeFull(tx.db.wal, frame); err != nil {
		return err
	}

	// This is the transaction's durability point. In-memory state is not
	// changed until the complete WAL frame has reached stable storage.
	if err := tx.db.wal.Sync(); err != nil {
		return err
	}

	applyOperations(tx.db.data, tx.ops)
	tx.db.seq = seq
	return nil
}

func (tx *Tx) Rollback() error {
	if tx.done {
		return nil
	}
	tx.done = true

	if tx.writable {
		tx.db.mu.Unlock()
	} else {
		tx.db.mu.RUnlock()
	}
	return nil
}

func cloneMap(src map[string][]byte) map[string][]byte {
	dst := make(map[string][]byte, len(src))
	for k, v := range src {
		dst[k] = append([]byte(nil), v...)
	}
	return dst
}
