`cmd/kvdb/main.go`
```go
package main

import (
	"encoding/hex"
	"errors"
	"flag"
	"fmt"
	"os"

	"kvdb"
)

func usage() {
	fmt.Fprintf(os.Stderr, `usage:
  kvdb -dir PATH get KEY
  kvdb -dir PATH put KEY VALUE
  kvdb -dir PATH delete KEY
  kvdb -dir PATH compact
  kvdb -dir PATH inspect

Values supplied to put are literal UTF-8 command-line bytes.
get writes raw value bytes followed by a newline.
`)
}

func main() {
	dir := flag.String("dir", "", "database directory")
	hexValue := flag.Bool("hex", false, "for put/get, encode value as hexadecimal")
	flag.Usage = usage
	flag.Parse()

	if *dir == "" || flag.NArg() < 1 {
		usage()
		os.Exit(2)
	}

	db, err := kvdb.Open(*dir)
	if err != nil {
		die(err)
	}
	defer db.Close()

	args := flag.Args()

	switch args[0] {
	case "get":
		if len(args) != 2 {
			usage()
			os.Exit(2)
		}
		v, ok, err := db.Get(args[1])
		if err != nil {
			die(err)
		}
		if !ok {
			os.Exit(1)
		}
		if *hexValue {
			fmt.Println(hex.EncodeToString(v))
		} else {
			if _, err := os.Stdout.Write(v); err != nil {
				die(err)
			}
			fmt.Println()
		}

	case "put":
		if len(args) != 3 {
			usage()
			os.Exit(2)
		}
		var v []byte
		if *hexValue {
			v, err = hex.DecodeString(args[2])
			if err != nil {
				die(err)
			}
		} else {
			v = []byte(args[2])
		}
		if err := db.Put(args[1], v); err != nil {
			die(err)
		}

	case "delete":
		if len(args) != 2 {
			usage()
			os.Exit(2)
		}
		if err := db.Delete(args[1]); err != nil {
			die(err)
		}

	case "compact":
		if len(args) != 1 {
			usage()
			os.Exit(2)
		}
		if err := db.Compact(); err != nil {
			die(err)
		}

	case "inspect":
		if len(args) != 1 {
			usage()
			os.Exit(2)
		}
		info, err := db.Inspect()
		if err != nil {
			die(err)
		}
		fmt.Printf("directory=%s\n", info.Directory)
		fmt.Printf("sequence=%d\n", info.Sequence)
		fmt.Printf("keys=%d\n", info.Keys)
		fmt.Printf("wal_bytes=%d\n", info.WALBytes)
		fmt.Printf("snapshot=%t\n", info.HasSnapshot)

	default:
		die(errors.New("unknown command: " + args[0]))
	}
}

func die(err error) {
	fmt.Fprintln(os.Stderr, "kvdb:", err)
	os.Exit(1)
}
