```go
package kvdb

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"testing"
	"time"
)

func TestCrashHelper(t *testing.T) {
	if os.Getenv("KVDB_CRASH_HELPER") != "1" {
		return
	}

	dir := os.Getenv("KVDB_CRASH_DIR")
	count, _ := strconv.Atoi(os.Getenv("KVDB_CRASH_COUNT"))

	db, err := Open(dir)
	if err != nil {
		os.Exit(20)
	}

	for i := 0; i < count; i++ {
		tx, err := db.Begin(true)
		if err != nil {
			os.Exit(21)
		}

		value := []byte(fmt.Sprintf("%08d", i))
		if err := tx.Put("last", value); err != nil {
			os.Exit(22)
		}
		if err := tx.Put("mirror", value); err != nil {
			os.Exit(23)
		}
		if err := tx.Commit(); err != nil {
			os.Exit(24)
		}

		// Signal only after Commit returned, so every value observed here must
		// survive a subsequent SIGKILL/TerminateProcess.
		fmt.Printf("%d\n", i)
	}

	select {}
}

func TestKillAfterCommittedTransactions(t *testing.T) {
	dir := t.TempDir()

	cmd := exec.Command(os.Args[0], "-test.run=^TestCrashHelper$")
	cmd.Env = append(os.Environ(),
		"KVDB_CRASH_HELPER=1",
		"KVDB_CRASH_DIR="+dir,
		"KVDB_CRASH_COUNT=200",
	)

	stdout, err := cmd.StdoutPipe()
	if err != nil {
		t.Fatal(err)
	}
	if err := cmd.Start(); err != nil {
		t.Fatal(err)
	}

	buf := make([]byte, 4096)
	total := ""
	deadline := time.Now().Add(10 * time.Second)

	for len(total) < 6 && time.Now().Before(deadline) {
		n, err := stdout.Read(buf)
		if n > 0 {
			total += string(buf[:n])
			if countLines(total) >= 5 {
				break
			}
		}
		if err != nil {
			break
		}
	}

	if countLines(total) < 1 {
		_ = cmd.Process.Kill()
		_ = cmd.Wait()
		t.Fatal("helper did not commit any transaction")
	}

	lines := splitNonemptyLines(total)
	last, err := strconv.Atoi(lines[len(lines)-1])
	if err != nil {
		t.Fatal(err)
	}

	if err := cmd.Process.Kill(); err != nil {
		t.Fatal(err)
	}
	_ = cmd.Wait()

	db, err := Open(dir)
	if err != nil {
		t.Fatalf("recovery failed after kill: %v", err)
	}
	defer db.Close()

	want := fmt.Sprintf("%08d", last)

	a, ok, err := db.Get("last")
	if err != nil || !ok {
		t.Fatalf("last missing: %v %v", ok, err)
	}
	b, ok, err := db.Get("mirror")
	if err != nil || !ok {
		t.Fatalf("mirror missing: %v %v", ok, err)
	}

	// Recovery can include transactions committed after the last line read,
	// because the child may run between the pipe read and Kill. Atomicity,
	// rather than exact equality to "last", is the important property.
	if string(a) != string(b) {
		t.Fatalf("transaction torn: last=%q mirror=%q", a, b)
	}
	if string(a) < want {
		t.Fatalf("acknowledged commit lost: got %q, acknowledged at least %q", a, want)
	}
}

