	})
	if err != nil {
		t.Fatal(err)
	}

	for cut := 1; cut < len(frame); cut++ {
		copyDir := t.TempDir()

		wal, err := os.ReadFile(filepath.Join(dir, walFileName))
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(copyDir, walFileName),
			append(append([]byte(nil), wal...), frame[:cut]...), 0600); err != nil {
			t.Fatal(err)
		}

		recovered, err := Open(copyDir)
		if err != nil {
			t.Fatalf("cut %d: %v", cut, err)
		}

		if _, ok, err := recovered.Get("partial"); err != nil || ok {
			recovered.Close()
			t.Fatalf("cut %d exposed incomplete transaction", cut)
		}

		v, ok, err := recovered.Get("stable")
		if err != nil || !ok || string(v) != "value" {
			recovered.Close()
			t.Fatalf("cut %d lost stable transaction", cut)
		}
		recovered.Close()
	}
}

func countLines(s string) int {
	n := 0
	for _, c := range s {
		if c == '\n' {
			n++
		}
	}
	return n
}

func splitNonemptyLines(s string) []string {
	var out []string
	start := 0
	for i := 0; i <= len(s); i++ {
		if i == len(s) || s[i] == '\n' {
			if i > start {
				out = append(out, s[start:i])
			}
			start = i + 1
		}
	}
	return out
}
```

The binary formats are deliberately small and deterministic. All integers are unsigned big-endian.

WAL file `wal` is a concatenation of transaction frames:

```text
offset  size  meaning
0       8     ASCII "KVWAL001"
8       4     payload length N, uint32
12      N     transaction payload
12+N    4     IEEE CRC-32 of exactly the N payload bytes
```

Each transaction payload is:

```text
8     transaction sequence number, uint64
4     operation count, uint32
repeated:
  1   operation type: 1=Put, 2=Delete
  4   key length K, uint32
  4   value length V, uint32
  K   raw key bytes
  V   raw value bytes; for Delete V must be zero
```

A Go string's bytes are stored exactly as supplied, so keys are not restricted to UTF-8. Values are arbitrary bytes.

The snapshot file `snapshot` is:

```text
8     ASCII "KVSNAP01"
8     payload length N, uint64
N     snapshot payload
4     IEEE CRC-32 of the payload
```

The snapshot payload is:

```text
8     highest incorporated transaction sequence, uint64
4     number of entries, uint32
repeated in lexicographic byte order by key:
  4   key length K, uint32
  4   value length V, uint32
  K   key
  V   value
```

Sorting makes snapshots deterministic for a given logical database state.

The central commit invariant is that `db.data` is never modified by an uncommitted write transaction. `Commit` first serializes the whole transaction into one checksummed WAL frame, appends all bytes, and calls `wal.Sync()`. Only after that sync succeeds are the operations installed in memory and `Commit()` allowed to return.

Consequently, the ordering is:

1. Acquire the exclusive writer lock.
2. Construct a complete transaction frame.
3. Append it to `wal`.
4. `fsync`/`File.Sync` the WAL.
5. Modify the in-memory state.
6. Return from `Commit`.

A crash before step 4 can leave no frame, a partial frame, or a torn final frame. Recovery scans only complete, correctly checksummed transactions. An incomplete final frame is discarded and the WAL is truncated back to the last valid frame. Because the in-memory database is updated only after the sync, incomplete transactions never become externally visible before a crash either.

There is an unavoidable storage-level distinction worth making explicit: an EOF WAL frame with the expected physical length but a bad checksum is indistinguishable from a torn final disk write. Recovery therefore treats a bad-CRC final frame as an incomplete transaction and discards it. A bad checksum or invalid framing before later WAL data is reported as `ErrCorrupt`. Snapshot corruption is always reported as `ErrCorrupt`. This provides CRC detection while also allowing deterministic recovery from torn final writes.

Compaction uses this ordering:

1. Hold the exclusive database lock.
2. Serialize the entire state and current sequence number to `snapshot.tmp`.
3. Write all snapshot bytes.
4. `Sync()` the temporary snapshot.
5. Atomically rename `snapshot.tmp` to `snapshot`.
6. Sync the database directory, making the rename durable.
7. Truncate the WAL to zero.
8. Sync the WAL.
9. Sync the directory again.

The WAL is never discarded before the new snapshot's rename is durable. A crash before the rename leaves the old snapshot plus the WAL. A crash after the rename but before WAL truncation leaves the new snapshot plus old WAL transactions. Their sequence numbers are no greater than the snapshot sequence and are therefore skipped during recovery. A crash after WAL truncation leaves the durable snapshot, so the WAL history is no longer needed.

Readers use `RWMutex.RLock`; multiple read transactions therefore run concurrently. A write transaction holds the exclusive lock for its lifetime, enforcing a single in-process writer and preventing readers from observing intermediate transaction state. This implementation does not provide cross-process concurrent-open locking; separate processes must not simultaneously open the same directory for writing.

