  th, td { border: 1px solid #ddd; padding: 6px 10px; text-align: left; font-size: 14px; }
  th { background: #eee; }
  .applied { color: #0a7a2f; font-weight: 600; }
  .stale { color: #b02a2a; }
</style>
</head>
<body>

<h2>Refresh Race Condition — Fixed</h2>
<button id="refreshBtn">Refresh</button>
<div id="result">No data yet.</div>

<table>
  <thead>
    <tr><th>Request ID</th><th>Timestamp</th><th>Status</th></tr>
  </thead>
  <tbody id="logBody"></tbody>
</table>

<script>
  // ---- Mocked fetch with random delay, so responses can arrive out of order ----
  function mockFetch(requestId, signal) {
    const delay = 300 + Math.random() * 1500; // 300ms–1.8s, random so late requests can resolve early
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        resolve({
          json: () => Promise.resolve({ value: 'Data for request #' + requestId, requestId })
        });
      }, delay);

      // Respect real cancellation via AbortController
      signal.addEventListener('abort', () => {
        clearTimeout(timer);
        const err = new Error('Aborted');
        err.name = 'AbortError';
        reject(err);
      });
    });
  }

  // ---- State ----
  let latestData = null;
  let currentRequestId = 0;   // increments on every click — the "source of truth" for relevance
  let activeController = null; // lets us actually cancel the in-flight request

  const resultEl = document.getElementById('result');
  const logBody = document.getElementById('logBody');
  const log = []; // { id, timestamp, status }

  function renderLog() {
    logBody.innerHTML = '';
    // show most recent 5, newest first
    log.slice(-5).reverse().forEach(entry => {
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td>${entry.id}</td>
        <td>${entry.timestamp}</td>
        <td class="${entry.status === 'applied' ? 'applied' : 'stale'}">${entry.status}</td>
      `;
      logBody.appendChild(tr);
    });
  }

  function updateLogStatus(id, status) {
    const entry = log.find(e => e.id === id);
    if (entry) entry.status = status;
    renderLog();
  }

  function refresh() {
    // Cancel whatever's still in flight — no point letting it keep running
    if (activeController) {
      activeController.abort();
    }

    currentRequestId += 1;
    const thisRequestId = currentRequestId;
    const controller = new AbortController();
    activeController = controller;

    const timestamp = new Date().toLocaleTimeString() + '.' + new Date().getMilliseconds();
    log.push({ id: thisRequestId, timestamp, status: 'pending' });
    renderLog();

    mockFetch(thisRequestId, controller.signal)
      .then(res => res.json())
      .then(data => {
        // Guard: only apply if this is still the latest request we care about
        if (thisRequestId !== currentRequestId) {
          updateLogStatus(thisRequestId, 'stale/discarded');
          return;
        }
        latestData = data;
        resultEl.textContent = data.value + ' (request #' + thisRequestId + ')';
        updateLogStatus(thisRequestId, 'applied');
      })
      .catch(err => {
        if (err.name === 'AbortError') {
          updateLogStatus(thisRequestId, 'stale/discarded');
        } else {
          updateLogStatus(thisRequestId, 'error');
        }
      });
  }

  document.getElementById('refreshBtn').addEventListener('click', refresh);
</script>

</body>
</html>
```

**Why this fixes it:**

1. **ID tracking** — every click increments `currentRequestId`. When a response comes back, it's only applied to `latestData`/the DOM if its own ID still matches `currentRequestId`. Any older response is marked `stale/discarded`, even if it happens to resolve *after* a newer one due to random network jitter.
2. **Real cancellation** — `AbortController` aborts the previous in-flight request the moment a new one starts, so you're not just ignoring stale data, you're actually stopping the wasted work (important for real fetches, not just the mock).
3. **Button stays enabled** — you can click rapidly and watch the table: most requests will show `stale/discarded`, and only the most recent one that resolves after all others have either completed or been superseded will show `applied`.

