    document.getElementById('stats').textContent = `Opens: ${opens} · Closes: ${closes}`;
  }

  function log(msg) {
    const el = document.getElementById('log');
    el.innerHTML = `${new Date().toLocaleTimeString()} — ${msg}<br>` + el.innerHTML;
  }

  verify(); // initial render
</script>
