    const trimmed = v.trim();
    // shape check: digits, spaces, parens, dashes, optional leading +
    const shapeOk = /^\+?[0-9\s().-]+$/.test(trimmed);
    const digitCount = trimmed.replace(/\D/g, "").length;
    return shapeOk && digitCount >= 7 && digitCount <= 15;
  }

  function isValidUrl(v) {
    return /^https?:\/\/[^\s]+\.[^\s]+/i.test(v.trim());
  }

  function isValidFileName(name) {
    return /\.(pdf|docx)$/i.test(name.trim());
  }

  function validateStep1() {
    const errs = {};
    if (!state.fullName.trim() || state.fullName.trim().length < 2) {
      errs.fullName = "Please enter your full name (at least 2 characters).";
    }
    if (!state.email.trim()) {
      errs.email = "Email is required.";
    } else if (!isValidEmail(state.email)) {
      errs.email = "Please enter a valid email address.";
    }
    if (!state.phone.trim()) {
      errs.phone = "Phone number is required.";
    } else if (!isValidPhone(state.phone)) {
      errs.phone = "Please enter a valid phone number (7–15 digits).";
    }
    return errs;
  }

  function validateStep2() {
    const errs = {};
    if (state.yearsExp === "" || state.yearsExp === null || state.yearsExp === undefined) {
      errs.yearsExp = "Years of experience is required.";
    } else {
      const n = Number(state.yearsExp);
      if (!Number.isInteger(n) || n < 0 || n > 40) {
        errs.yearsExp = "Enter a whole number between 0 and 40.";
      }
    }
    if (state.skills.length < 2) {
      errs.skills = "Select at least 2 skills.";
    }
    if (state.skills.includes("Design")) {
      if (!state.portfolioUrl.trim()) {
        errs.portfolioUrl = "Portfolio URL is required when Design is selected.";
      } else if (!isValidUrl(state.portfolioUrl)) {
        errs.portfolioUrl = "Enter a valid URL (e.g. https://your-portfolio.com).";
      }
    }
    return errs;
  }

  function validateStep3() {
    const errs = {};
    if (!state.fileName) {
      errs.file = "Please attach a file.";
    } else if (!isValidFileName(state.fileName)) {
      errs.file = "Only .pdf or .docx files are accepted.";
    }
    const len = state.coverLetter.trim().length;
    if (len < 100) {
      errs.coverLetter = `Cover letter is too short (${len}/100 minimum characters).`;
    } else if (len > 1000) {
      errs.coverLetter = `Cover letter is too long (${len}/1000 maximum characters).`;
    }
    return errs;
  }

  function validateStep4() {
    const errs = {};
    if (!state.confirmed) {
      errs.confirmed = "Please confirm your data is accurate.";
    }
    return errs;
  }

  const stepValidators = { 1: validateStep1, 2: validateStep2, 3: validateStep3, 4: validateStep4 };

  // ---------- Rendering ----------
  function render() {
    progressLabel.textContent = `Step ${state.step} / 4`;
    progressFill.style.width = (state.step / 4 * 100) + "%";

    backBtn.disabled = state.step === 1;
    navRow.style.display = state.submitted ? "none" : "flex";
    nextBtn.textContent = state.step === 4 ? "Submit" : "Next";
    nextBtn.disabled = state.step === 4 && !state.confirmed;

    if (state.submitted) {
      stepContainer.innerHTML = `
        <div class="success-box">
          <h2>Application submitted!</h2>
          <p>Thanks, ${escapeHtml(state.fullName)} — we've received your application.</p>
        </div>`;
      navRow.style.display = "none";
      return;
    }

    if (state.step === 1) renderStep1();
    else if (state.step === 2) renderStep2();
    else if (state.step === 3) renderStep3();
    else if (state.step === 4) renderStep4();
  }

  function escapeHtml(str) {
    const div = document.createElement("div");
    div.textContent = str ?? "";
    return div.innerHTML;
  }

  function errorTag(field) {
    return state.errors[field] ? `<div class="error-msg">${escapeHtml(state.errors[field])}</div>` : "";
  }

  function invalidClass(field) {
    return state.errors[field] ? "invalid" : "";
  }

  // ---- Step 1 ----
  function renderStep1() {
    stepContainer.innerHTML = `
      <div class="step-title">Personal Information</div>
      <div class="field">
        <label for="fullName">Full name</label>
        <input type="text" id="fullName" class="${invalidClass('fullName')}" value="${escapeHtml(state.fullName)}">
        ${errorTag('fullName')}
      </div>
      <div class="field">
        <label for="email">Email</label>
        <input type="email" id="email" class="${invalidClass('email')}" value="${escapeHtml(state.email)}">
        ${errorTag('email')}
      </div>
      <div class="field">
        <label for="phone">Phone</label>
        <input type="tel" id="phone" class="${invalidClass('phone')}" placeholder="+1 555 123 4567" value="${escapeHtml(state.phone)}">
        ${errorTag('phone')}
      </div>
    `;
    document.getElementById("fullName").addEventListener("input", e => {
      state.fullName = e.target.value;
      clearFieldError('fullName', e.target);
    });
    document.getElementById("email").addEventListener("input", e => {
      state.email = e.target.value;
      clearFieldError('email', e.target);
    });
    document.getElementById("phone").addEventListener("input", e => {
      state.phone = e.target.value;
      clearFieldError('phone', e.target);
    });
  }

  // ---- Step 2 ----
  function renderStep2() {
    const showPortfolio = state.skills.includes("Design");
    stepContainer.innerHTML = `
      <div class="step-title">Experience & Skills</div>
      <div class="field">
        <label for="yearsExp">Years of experience (0–40)</label>
        <input type="number" id="yearsExp" min="0" max="40" step="1" class="${invalidClass('yearsExp')}" value="${escapeHtml(String(state.yearsExp))}">
        ${errorTag('yearsExp')}
      </div>
      <div class="field">
        <label>Skills (select at least 2)</label>
        <div class="skills-grid">
          ${SKILL_OPTIONS.map(s => `
            <label class="skill-option">
              <input type="checkbox" data-skill="${s}" ${state.skills.includes(s) ? "checked" : ""}>
              ${s}
            </label>
          `).join("")}
        </div>
        ${errorTag('skills')}
      </div>
      ${showPortfolio ? `
        <div class="field" id="portfolioField">
          <label for="portfolioUrl">Portfolio URL</label>
          <input type="url" id="portfolioUrl" class="${invalidClass('portfolioUrl')}" placeholder="https://..." value="${escapeHtml(state.portfolioUrl)}">
          ${errorTag('portfolioUrl')}
        </div>
      ` : ""}
    `;

    document.getElementById("yearsExp").addEventListener("input", e => {
      state.yearsExp = e.target.value;
      clearFieldError('yearsExp', e.target);
    });

    stepContainer.querySelectorAll('input[type="checkbox"][data-skill]').forEach(cb => {
      cb.addEventListener("change", e => {
        const skill = e.target.getAttribute("data-skill");
        if (e.target.checked) {
          if (!state.skills.includes(skill)) state.skills.push(skill);
        } else {
          state.skills = state.skills.filter(s => s !== skill);
          if (skill === "Design") {
            // Design deselected: clear its error, keep typed URL in state
            delete state.errors.portfolioUrl;
          }
        }
        delete state.errors.skills;
        renderStep2(); // re-render to show/hide portfolio field
      });
    });

    const portfolioInput = document.getElementById("portfolioUrl");
    if (portfolioInput) {
      portfolioInput.addEventListener("input", e => {
        state.portfolioUrl = e.target.value;
        clearFieldError('portfolioUrl', e.target);
      });
    }
  }

  // ---- Step 3 ----
  function renderStep3() {
    const len = state.coverLetter.trim().length;
    const counterBad = len < 100 || len > 1000;
    stepContainer.innerHTML = `
      <div class="step-title">Documents & Cover Letter</div>
      <div class="field">
        <label for="fileInput">Resume (.pdf or .docx)</label>
        <div class="file-btn-row">
          <input type="file" id="fileInput" accept=".pdf,.docx">
        </div>
        <div class="file-name">${state.fileName ? "Selected: " + escapeHtml(state.fileName) : ""}</div>
        ${errorTag('file')}
      </div>
      <div class="field">
        <label for="coverLetter">Cover letter</label>
        <textarea id="coverLetter" class="${invalidClass('coverLetter')}">${escapeHtml(state.coverLetter)}</textarea>
        <div class="counter ${counterBad ? 'bad' : ''}" id="counterText">${len} / 1000 characters (min 100)</div>
        ${errorTag('coverLetter')}
      </div>
    `;

    document.getElementById("fileInput").addEventListener("change", e => {
      const file = e.target.files[0];
      if (file) {
        state.fileName = file.name;
        if (!isValidFileName(file.name)) {
          state.errors.file = "Only .pdf or .docx files are accepted.";
        } else {
          delete state.errors.file;
        }
      } else {
        state.fileName = "";
      }
      renderStep3();
    });

    const textarea = document.getElementById("coverLetter");
    const counterText = document.getElementById("counterText");
    textarea.addEventListener("input", e => {
      state.coverLetter = e.target.value;
      const l = state.coverLetter.trim().length;
      const bad = l < 100 || l > 1000;
      counterText.textContent = `${l} / 1000 characters (min 100)`;
      counterText.classList.toggle("bad", bad);
      clearFieldError('coverLetter', textarea);
    });
  }

  // ---- Step 4 ----
  function renderStep4() {
    stepContainer.innerHTML = `
      <div class="step-title">Review Your Application</div>
      <div class="review-block">
        <div class="review-row"><span class="review-label">Full name</span><span class="review-value">${escapeHtml(state.fullName)}</span></div>
        <div class="review-row"><span class="review-label">Email</span><span class="review-value">${escapeHtml(state.email)}</span></div>
        <div class="review-row"><span class="review-label">Phone</span><span class="review-value">${escapeHtml(state.phone)}</span></div>
      </div>
      <div class="review-block">
        <div class="review-row"><span class="review-label">Years of experience</span><span class="review-value">${escapeHtml(String(state.yearsExp))}</span></div>
        <div class="review-row"><span class="review-label">Skills</span><span class="review-value">${escapeHtml(state.skills.join(", "))}</span></div>
        ${state.skills.includes("Design") ? `<div class="review-row"><span class="review-label">Portfolio URL</span><span class="review-value">${escapeHtml(state.portfolioUrl)}</span></div>` : ""}
      </div>
      <div class="review-block">
        <div class="review-row"><span class="review-label">Resume file</span><span class="review-value">${escapeHtml(state.fileName)}</span></div>
        <div class="review-row"><span class="review-label">Cover letter</span><span class="review-value">${escapeHtml(state.coverLetter)}</span></div>
      </div>
      <div class="confirm-row">
        <input type="checkbox" id="confirmCheck" ${state.confirmed ? "checked" : ""}>
        <label for="confirmCheck" style="margin:0;font-weight:400;">I confirm this is accurate</label>
      </div>
      ${errorTag('confirmed')}
    `;
    document.getElementById("confirmCheck").addEventListener("change", e => {
      state.confirmed = e.target.checked;
      delete state.errors.confirmed;
      nextBtn.disabled = !state.confirmed;
    });
  }

  function clearFieldError(field, inputEl) {
    if (state.errors[field]) {
      delete state.errors[field];
      inputEl.classList.remove("invalid");
      const err = inputEl.parentElement.querySelector(".error-msg");
      if (err) err.remove();
    }
  }

  // ---------- Navigation ----------
  backBtn.addEventListener("click", () => {
    if (state.step > 1) {
      state.step -= 1;
      state.errors = {};
      render();
    }
  });

  nextBtn.addEventListener("click", () => {
    const validator = stepValidators[state.step];
    const errs = validator();
    state.errors = errs;

    if (Object.keys(errs).length > 0) {
      render(); // re-render current step with inline errors, do not advance
      return;
    }

    if (state.step < 4) {
      state.step += 1;
      state.errors = {};
      render();
    } else {
      // Step 4: submit
      state.submitted = true;
      render();
    }
  });

  // ---------- Init ----------
  render();
</script>
</body>
</html>
```

A few implementation notes worth knowing:

- **Portfolio URL edge case**: if a user fills it in, checks "Design" off, then back on, the typed value is preserved in state (only the *error* is cleared when unchecked) — so they don't have to retype it.
- **Step 3's counter** updates on every keystroke without a full re-render (so focus/cursor position isn't lost), while file selection does a full `renderStep3()` since it's a discrete, infrequent event.
- Every dynamic value inserted into `innerHTML` goes through `escapeHtml()` to avoid HTML injection from user-entered text (e.g., a cover letter containing `<script>`).
- Since code execution/artifacts aren't enabled in this chat, I've put the file inline above — copy it into a `.html` file and open it in a browser to run it.

## Reasoning

**Layout structure:** I'll use a CSS Grid on the `<body>`/wrapper: `grid-template-columns: 280px 1fr` on desktop (sidebar + main), collapsing to a single column on mobile/tablet where the sidebar becomes an off-canvas drawer (`position: fixed`, `transform: translateX(-100%)` by default, toggled to `translateX(0)` via a `.open` class) with a semi-transparent backdrop overlay to close it. The main content area itself uses a CSS Grid for the product cards: `grid-template-columns: repeat(4, 1fr)` desktop, `repeat(2, 1fr)` tablet, `repeat(1, 1fr)` mobile — controlled by simple `min-width` media queries at 640px and 1024px (mobile-first, so base styles are mobile/1-column).

**Breakpoint behavior:**
- **<640px (mobile):** Sidebar is a fixed-position drawer hidden off-screen, revealed by a hamburger button in the sticky top bar. Product grid is 1 column. Top bar content (title / count / sort) wraps via `flex-wrap: wrap` and reduces font size so nothing overflows at 320px.
- **640–1024px (tablet):** Same drawer behavior (still off-canvas, since a fixed 280px sidebar would eat too much of a 640–1024px viewport), product grid becomes 2 columns.
- **>1024px (desktop):** Sidebar becomes static/in-flow (`position: static`, always visible, no transform, hamburger hidden), grid becomes 4 columns, main grid layout (`280px 1fr`) applies.

I gate the "drawer vs static" sidebar behavior with a `min-width: 1025px` media query that overrides the fixed positioning.

**State sync (no reload):** A single JS `state` object holds `{minPrice, maxPrice, categories: Set, rating, sort}`. Every filter input (number inputs, checkboxes, radios, sort select) has an event listener that mutates `state` and then calls one `render()` function. `render()` runs a pure filter+sort pass over the hardcoded `products` array and rebuilds the grid's innerHTML plus the "Showing X of Y" counter — this is the single source of truth, so sidebar and grid never desync since both read/write the same object. "Clear all filters" just resets `state` to defaults, resets form controls, and calls `render()`. No frameworks, no page reload, just direct DOM diffless re-render (cheap enough for 12–20 items).

I mentally traced 320px: hamburger + title + sort collapse into a wrapped flex row, drawer is `100%`-capped width with `max-width: 300px`, cards shrink to full width with padding — no horizontal scroll or overlap.

