    { id: 15, name: "Sunglasses",               price: 39.99,  category: "Accessories",rating: 3.7 },
  ];

  const categories = [...new Set(products.map(p => p.category))].sort();

  // ---------- State ----------
  const state = {
    minPrice: 0,
    maxPrice: 500,
    categories: new Set(),
    rating: 0,
    sort: "default"
  };

  // ---------- DOM refs ----------
  const grid = document.getElementById("productGrid");
  const resultCount = document.getElementById("resultCount");
  const categoryList = document.getElementById("categoryList");
  const minPriceInput = document.getElementById("minPrice");
  const maxPriceInput = document.getElementById("maxPrice");
  const sortSelect = document.getElementById("sortSelect");
  const sidebar = document.getElementById("sidebar");
  const overlay = document.getElementById("overlay");

  // ---------- Build category checkboxes ----------
  categories.forEach(cat => {
    const label = document.createElement("label");
    label.className = "checkbox-row";
    label.innerHTML = `<input type="checkbox" value="${cat}"> ${cat}`;
    label.querySelector("input").addEventListener("change", (e) => {
      if (e.target.checked) state.categories.add(cat);
      else state.categories.delete(cat);
      render();
    });
    categoryList.appendChild(label);
  });

  // ---------- Sidebar drawer toggle ----------
  document.getElementById("openSidebar").addEventListener("click", () => {
    sidebar.classList.add("open");
    overlay.classList.add("show");
  });
  function closeDrawer() {
    sidebar.classList.remove("open");
    overlay.classList.remove("show");
  }
  document.getElementById("closeSidebar").addEventListener("click", closeDrawer);
  overlay.addEventListener("click", closeDrawer);

  // ---------- Filter inputs ----------
  minPriceInput.addEventListener("input", () => {
    state.minPrice = Number(minPriceInput.value) || 0;
    render();
  });
  maxPriceInput.addEventListener("input", () => {
    state.maxPrice = maxPriceInput.value === "" ? Infinity : Number(maxPriceInput.value);
    render();
  });
  document.querySelectorAll('input[name="rating"]').forEach(radio => {
    radio.addEventListener("change", (e) => {
      state.rating = Number(e.target.value);
      render();
    });
  });
  sortSelect.addEventListener("change", () => {
    state.sort = sortSelect.value;
    render();
  });
  document.getElementById("clearFilters").addEventListener("click", () => {
    state.minPrice = 0;
    state.maxPrice = 500;
    state.categories.clear();
    state.rating = 0;
    state.sort = "default";

    minPriceInput.value = 0;
    maxPriceInput.value = 500;
    sortSelect.value = "default";
    document.querySelectorAll('#categoryList input[type="checkbox"]').forEach(cb => cb.checked = false);
    document.querySelector('input[name="rating"][value="0"]').checked = true;

    render();
  });

  // ---------- Core filter + sort + render ----------
  function getFilteredProducts() {
    let result = products.filter(p => {
      const priceOk = p.price >= state.minPrice && p.price <= state.maxPrice;
      const categoryOk = state.categories.size === 0 || state.categories.has(p.category);
      const ratingOk = p.rating >= state.rating;
      return priceOk && categoryOk && ratingOk;
    });

    switch (state.sort) {
      case "price-asc":  result.sort((a, b) => a.price - b.price); break;
      case "price-desc": result.sort((a, b) => b.price - a.price); break;
      case "rating-desc":result.sort((a, b) => b.rating - a.rating); break;
      default: break;
    }
    return result;
  }

  function renderCard(p) {
    return `
      <div class="card">
        <div class="card-thumb">${p.name.charAt(0)}</div>
        <h3>${p.name}</h3>
        <div class="category">${p.category}</div>
        <div class="meta">
          <span class="price">$${p.price.toFixed(2)}</span>
          <span class="rating">&#9733; ${p.rating.toFixed(1)}</span>
        </div>
      </div>
    `;
  }

  function render() {
    const filtered = getFilteredProducts();

    if (filtered.length === 0) {
      grid.innerHTML = `
        <div class="empty-state">
          <div class="icon">&#128269;</div>
          <div>No products match your filters.</div>
        </div>
      `;
    } else {
      grid.innerHTML = filtered.map(renderCard).join("");
    }

    resultCount.textContent = `Showing ${filtered.length} of ${products.length} products`;
  }

  // ---------- Init ----------
  render();
</script>

</body>
</html>
```

**Notes on the tricky bits:**
- The sidebar switches from a fixed-position drawer to a static in-flow column purely via the `min-width: 1025px` media query — no JS branching needed for desktop vs mobile behavior.
- All filter/sort controls mutate one `state` object and call the same `render()`, so the sidebar and grid can never drift out of sync — there's no separate "apply" step.
- `min-width: 0` is set on `.main` and `.card` to stop grid/flex items from refusing to shrink below content size, which is what usually causes horizontal overflow at 320px.

